102	
103	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
104	        let node = ctx.query();
105	
106	        // Check if element is an anchor tag
107	        // In HTML files, tag names are case-insensitive
108	        // In component frameworks (Vue, Svelte, Astro), only lowercase is checked
109	        let element_name = node.name()?;
110	        let source_type = ctx.source_type::<HtmlFileSource>();
111	        let is_anchor = if source_type.is_html() {
112	            element_name.text().eq_ignore_ascii_case("a")
113	        } else {
114	            element_name.text() == "a"
115	        };
116	        if !is_anchor {
117	            return None;
118	        }
119	
120	        // Check if the anchor itself has aria-hidden attribute
121	        if let Some(aria_hidden_attr) = get_truthy_aria_hidden_attribute(node) {
122	            return Some(UseAnchorContentState {
123	                aria_hidden_attribute: Some(aria_hidden_attr),
124	            });
125	        }
126	
127	        // Check if anchor has accessible name via aria-label or title
128	        if has_accessible_name(node) {
129	            return None;
130	        }
131	
132	        // Handle self-closing anchors - they have no content
133	        if node.as_html_element().is_none() {
134	            return Some(UseAnchorContentState {
135	                aria_hidden_attribute: None,
136	            });
137	        }
138	
139	        let html_element = node.as_html_element()?;
140	        // Skip analysis if we can't fully parse the element to avoid false positives
141	        if html_element.opening_element().is_err() {
142	            return None;
143	        }
144	
145	        // Check if the anchor has accessible content
146	        let is_astro = source_type.is_astro();
147	        if has_accessible_content(&html_element.children(), is_astro) {
148	            return None;
149	        }
150	
151	        // No accessible content found - emit diagnostic
152	        Some(UseAnchorContentState {
153	            aria_hidden_attribute: None,
154	        })
155	    }
