179	    fn action(ctx: &RuleContext<Self>, state: &Self::State) -> Option<HtmlRuleAction> {
180	        let aria_hidden = state.aria_hidden_attribute.as_ref()?;
181	        let mut mutation = ctx.root().begin();
182	        mutation.remove_node(aria_hidden.clone());
183	
