129	/// check if the node has a valid heading attribute
130	fn has_valid_heading_content(node: &AnyJsxElement) -> bool {
131	    node.find_attribute_by_name("dangerouslySetInnerHTML")
132	        .is_some()
133	        || node
134	            .find_attribute_by_name("children")
135	            .is_some_and(|attribute| {
136	                if attribute.initializer().is_none() {
137	                    return false;
138	                }
139	                attribute
140	                    .as_static_value()
141	                    .is_none_or(|attribute| !attribute.is_falsy())
142	            })
143	        || node.has_spread_prop()
144	}
